"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[98093],{98093:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/towards-midnight.png\\"\\n          title=\\"Towards Zero\\"\\n          author=\\"Agatha Christie\\"\\n          publisher=\\"Golden Bough\\"\\n          publishedDate=\\"2013-05-27\\"\\n          isbn=\\"9788982737046\\"\\n          rating=4\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\nA work where the twist of the true culprit and the real mastermind behind it bring a shocking conclusion.\\nA sophisticated trick that deceives the reader twice with multi-layered tricks and twists. This is indeed the ```Queen of Crime```.  \\n<br>\\nThe psychological depiction that well expresses the darkness within human nature also stands out.  \\n<br>\\nThe original title is also <mark>Towards Zero</mark>, seemingly because it views a murder case as the ```destination``` rather than the ```beginning``` of the story.\\nIn other words, from the perspective of this novel, a murder case is not a sudden accident, but a result where the pasts, desires, conflicts, and plans of various characters who seemed unrelated to each other flow and converge toward a single peak of ```murder```, namely **\'Zero Hour\'**, just as multiple rivers gather into one sea.  \\n<br>\\nIt was a work where one can see the true worth of <mark>Agatha Christie</mark>.  "}')}}]);